@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE)
class DemoBusinessTest {
    static final Path DATABASE;
    static {try{DATABASE=Files.createTempDirectory("wms-demo-tests-").resolve("isolated.sqlite");}catch(Exception e){throw new RuntimeException(e);}}
    @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("app.database.path",()->DATABASE.toString());}
    @Autowired DemoRepository repo;@Autowired DemoSeeder seed;@Autowired DemoAuth auth;@Autowired DemoAssetService assets;@Autowired DemoPlanService plans;@Autowired DemoReportData reports;@Autowired DemoAgentEngine engine;
    @MockBean DeepSeekClient client;
    Actor admin,stock,tech;
    @BeforeEach void prepare()throws Exception{
        repo.tx(()->{repo.jdbc().update("DELETE FROM demo_records");repo.jdbc().update("DELETE FROM demo_trace");repo.jdbc().update("DELETE FROM demo_uploads");repo.jdbc().update("DELETE FROM demo_sessions");repo.jdbc().update("UPDATE demo_users SET revision=1,active=1");return null;});seed.initialize();
        admin=actor("admin");stock=actor("factory01");tech=actor("tech02");when(client.status()).thenReturn(map("model","injected-test-model","configured",true));
    }
    Actor actor(String user){return auth.authenticate("Bearer "+auth.login(user,"Demo@2026").get("token"));}
    byte[] fixture(String name)throws Exception{return StreamUtils.copyToByteArray(new ClassPathResource("demo/files/"+name).getInputStream());}
    byte[] csv(String code,String... replacements){String[] row={code,"测试设备","待确认","主","磨粉生产线","生产部","2024-01-15","100.00","完好","2023-11","在用","生产机械","工艺设备","购置"};for(int i=0;i<replacements.length;i+=2)row[Integer.parseInt(replacements[i])]=replacements[i+1];return (String.join(",",DemoAssetService.HEADERS)+"\n"+String.join(",",row)+"\n").getBytes(StandardCharsets.UTF_8);}
    Map<String,Object> preview(byte[] bytes){return assets.preview(admin,"F01","assets","","test.csv",bytes);}
    Map<String,Object> draft(String id,String state){return plans.propose(admin,map("action","update","task_id",id,"state",state,"note","测试跟进"));}
    String cardId(Map<String,Object> c){return str(obj(c.get("confirmation")),"id");}
    @Test void seedsStableTwelveFactoryCountsAndPersistsWithoutDuplication()throws Exception{
        assertEquals(432,assets.records(admin,"ALL").size());Map<String,Object> r=assets.search(admin,map("factory_id","F01"));assertEquals(36,r.get("total"));assertEquals(24,r.get("process_count"));assertEquals(9L,r.get("nonprocess_count"));assertEquals(3L,r.get("unclassified_count"));seed.initialize();assertEquals(432,assets.records(admin,"ALL").size());assertTrue(Files.size(DATABASE)>0);
    }
    @Test void sessionsPasswordLogoutRevocationAndFactoryIsolation(){
        assertThrows(BusinessException.class,()->auth.login("admin","wrong"));String token="Bearer "+auth.login("factory01","Demo@2026").get("token");assertEquals("F01",auth.authenticate(token).factory);auth.logout(token);assertThrows(BusinessException.class,()->auth.authenticate(token));
        assertThrows(BusinessException.class,()->assets.search(stock,map("factory_id","F02")));assertThrows(BusinessException.class,()->assets.get(stock,"AS-F02-0025"));assertThrows(BusinessException.class,()->reports.energy(stock,map("factory_id","F02","start","2026-11-01","end","2026-11-16")));auth.revoke(admin,"factory01");assertThrows(BusinessException.class,()->auth.scope(stock,"F01"));
    }
    @Test void confirmedSnapshotNeverCreatesOrOverwritesAssetsAndRetriesAreIdempotent()throws Exception{
        byte[] input=fixture("F03_C_2026-10_模拟盘点.csv");Map<String,Object> b=assets.preview(admin,"F03","snapshot","2026-10","c.csv",input);assertEquals("C",b.get("format"));assertEquals("preview",b.get("state"));assertNull(reports.latestSnapshot(admin,"F03","2026-10"));Map<String,Object> result=assets.commit(admin,str(b,"id"));assertEquals(result.get("snapshot_id"),assets.commit(admin,str(b,"id")).get("snapshot_id"));assertEquals(36,assets.records(admin,"F03").size());assertEquals(1,repo.get("AS-F03-0001").get("version"));assertEquals(36,rows(reports.latestSnapshot(admin,"F03","2026-10").get("rows")).size());
    }
    @Test void allThreeDefinedMappingsAndUnknownHeadersAreHandled()throws Exception{
        for(String f:Arrays.asList("F01_A_2026-10_模拟盘点.csv","F02_B_2026-10_模拟盘点.csv","F03_C_2026-10_模拟盘点.csv")){Map<String,Object> b=assets.preview(admin,f.substring(0,3),"snapshot","2026-10",f,fixture(f));assertEquals("preview",b.get("state"));assertEquals(36,rows(b.get("rows")).size());}
        Map<String,Object> b=assets.preview(admin,"F03","snapshot","2026-10","bad.csv",fixture("F03_C_缺少运行状态_错误样例.csv"));assertEquals("invalid",b.get("state"));assertThrows(BusinessException.class,()->assets.commit(admin,str(b,"id")));
    }
    @ParameterizedTest @CsvSource({"0,=attack","7,-1","7,1.234","6,2026-02-30","9,2026-13","10,飞行中","12,未知分类","3,特级","4,不存在产线"})
    void invalidRowsLeaveBusinessTablesUntouched(String column,String value){Map<String,Object> b=preview(csv("TEST-001",column,value));assertEquals("invalid",b.get("state"));assertThrows(BusinessException.class,()->assets.commit(admin,str(b,"id")));assertEquals(432,assets.records(admin,"ALL").size());}
    @Test void addedAssetRetainsLeadingZerosAndDuplicateImportIsRejected(){Map<String,Object> b=preview(csv("00000001"));assertEquals("preview",b.get("state"));assets.commit(admin,str(b,"id"));assets.commit(admin,str(b,"id"));assertEquals(37,assets.records(admin,"F01").size());assertEquals("00000001",assets.records(admin,"F01").stream().filter(a->str(a,"code").equals("00000001")).findFirst().get().get("code"));assertEquals("invalid",preview(csv("00000001")).get("state"));}
    @Test void previewDoesNotWriteAndConfirmationRechecksCurrentVersion()throws Exception{Map<String,Object> b=assets.preview(admin,"F01","snapshot","2026-10","a.csv",fixture("F01_A_2026-10_模拟盘点.csv"));Map<String,Object> a=repo.get("AS-F01-0001");a.put("importance","重要");repo.save(a);assertThrows(BusinessException.class,()->assets.commit(admin,str(b,"id")));
        Map<String,Object> newBatch=preview(csv("NEW-001"));assertEquals(36,assets.records(admin,"F01").size());assertThrows(BusinessException.class,()->assets.commit(stock,str(newBatch,"id")));}
    @Test void batchClassificationRollsBackAtomicallyOnAnyConflict(){Map<String,Object> first=repo.get("AS-F01-0001"),second=repo.get("AS-F01-0002");assertThrows(BusinessException.class,()->assets.classify(admin,map("assets",Arrays.asList(map("id",first.get("id"),"version",first.get("version")),map("id",second.get("id"),"version",999)),"classification","非工艺设备","importance","重要","reason","测试")));assertEquals("工艺设备",repo.get("AS-F01-0001").get("classification"));assertEquals(1,repo.get("AS-F01-0001").get("version"));assertThrows(BusinessException.class,()->assets.classify(tech,map("assets",Arrays.asList(map("id","AS-F02-0001","version",1)),"classification","非工艺设备","reason","测试")));}
    @Test void voidBatchRetainsHistoryAndPreventsDeletionWithReferences(){Map<String,Object> b=preview(csv("VOID-001"));assets.commit(admin,str(b,"id"));assertEquals(1,assets.voidBatch(admin,str(b,"id")).get("voided"));assertEquals(36,assets.records(admin,"F01").size());assertEquals("void",repo.get(str(b,"id")).get("state"));
        Map<String,Object> next=preview(csv("REF-001"));assets.commit(admin,str(next,"id"));Map<String,Object> asset=assets.records(admin,"F01").stream().filter(r->str(r,"code").equals("REF-001")).findFirst().get();assets.approval(admin,map("asset_id",asset.get("id"),"description","申请核对","request_key","test-ref"));assertThrows(BusinessException.class,()->assets.voidBatch(admin,str(next,"id")));}
    @Test void approvalIsIdempotentAndDoesNotChangeClassification(){Map<String,Object> p=map("asset_id","AS-F01-0001","description","分类核对","request_key","same");Map<String,Object> a=assets.approval(stock,p);assertEquals(a.get("id"),assets.approval(stock,p).get("id"));assertEquals(1,repo.all("approval").size());assertEquals("工艺设备",repo.get("AS-F01-0001").get("classification"));assertEquals(0,assets.approvals(tech).size());}
    @Test void writesNeedConfirmationAndDoubleConfirmationHasOneEffect()throws Exception{Map<String,Object> c=draft("WX-02-001","进行中");assertEquals("待执行",repo.get("WX-02-001").get("state"));ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Map<String,Object>> one=pool.submit(()->plans.confirm(admin,cardId(c),false)),two=pool.submit(()->plans.confirm(admin,cardId(c),false));assertEquals(one.get().get("id"),two.get().get("id"));}finally{pool.shutdownNow();}assertEquals("进行中",repo.get("WX-02-001").get("state"));assertEquals(2,repo.get("WX-02-001").get("version"));assertEquals(1L,repo.all("event").stream().filter(r->str(r,"action").equals("confirm_plan_change")).count());}
    @Test void cancelledExpiredConflictingAndRevokedCardsCannotWrite(){Map<String,Object> cancelled=draft("WX-02-001","进行中");plans.confirm(admin,cardId(cancelled),true);assertThrows(BusinessException.class,()->plans.confirm(admin,cardId(cancelled),false));Map<String,Object> expired=draft("WX-02-001","进行中"),card=repo.get(cardId(expired));card.put("expires_at","2000-01-01T00:00:00+08:00");repo.save(card);assertThrows(BusinessException.class,()->plans.confirm(admin,cardId(expired),false));Map<String,Object> first=draft("WX-02-001","进行中"),second=draft("WX-02-001","进行中");plans.confirm(admin,cardId(first),false);assertThrows(BusinessException.class,()->plans.confirm(admin,cardId(second),false));Map<String,Object> techCard=plans.propose(tech,map("action","update","task_id","WX-02-002","state","受阻"));auth.revoke(admin,"tech02");assertThrows(BusinessException.class,()->plans.confirm(tech,cardId(techCard),false));}
    @Test void taskOwnershipTransitionsResultsAndCreateDraftAreEnforced(){assertThrows(BusinessException.class,()->plans.propose(tech,map("action","update","task_id","WX-01-001","state","进行中")));assertThrows(BusinessException.class,()->draft("WX-02-004","进行中"));assertThrows(BusinessException.class,()->draft("WX-02-002","已完成"));
        Map<String,Object> done=plans.propose(admin,map("action","update","task_id","WX-02-002","state","已完成","result","已检修试车","completed_at","2026-11-16"));plans.confirm(admin,cardId(done),false);assertEquals("2026-11-16",repo.get("WX-02-002").get("completed_at"));int count=repo.all("plan").size();Map<String,Object> c=plans.propose(admin,map("action","create","asset_id","AS-F02-0025","type","零星维修","title","空调检修","deadline","2026-11-25","assignee","tech02"));assertEquals(count,repo.all("plan").size());plans.confirm(admin,cardId(c),false);assertEquals(count+1,repo.all("plan").size());}
    @Test void snapshotEvidenceTemplateAndPartialCoverageAreBound(){Map<String,Object> one=reports.collect(admin,"F01","2026-10","V1","SN-F01-2026-10",reports.frozenPlanMetrics(admin,"F01","2026-10"));assertFalse(obj(one.get("metrics")).containsKey("stopped"));Map<String,Object> two=reports.collect(admin,"F02","2026-10","V2","SN-F02-2026-10",reports.frozenPlanMetrics(admin,"F02","2026-10"));assertEquals(6,obj(two.get("metrics")).get("stopped"));Map<String,Object> missing=reports.collect(admin,"F03","2026-10","V2","",map());assertEquals("needs_input",missing.get("status"));Map<String,Object> total=reports.aggregate(Arrays.asList(one,two,two,missing),Arrays.asList("F01","F02","F03"),"2026-10","V2");assertEquals(72,obj(total.get("metrics")).get("total"));assertEquals(Arrays.asList("F03"),total.get("missing_factories"));assertThrows(BusinessException.class,()->reports.collect(admin,"F01","2026-10","V2","SN-F02-2026-10",map()));}
    @Test void energyDoesNotReplaceMissingWithZeroAndHandlesZeroBaseline(){Map<String,Object> q=map("factory_id","F02","start","2026-11-01","end","2026-11-16","compare_start","2026-10-01","compare_end","2026-10-16");Map<String,Object> r=reports.energy(admin,q);assertEquals(120.0,r.get("current"));assertEquals("20.00",r.get("change_percent").toString());q.put("start","2026-12-01");q.put("end","2026-12-16");assertNull(reports.energy(admin,q).get("current"));q.put("start","2026-11-01");q.put("end","2026-11-16");Map<String,Object> e=repo.get("EN-F02");rows(e.get("periods")).get(0).put("value",0);repo.save(e);assertNull(reports.energy(admin,q).get("change_percent"));q.put("end","2026-11-17");assertThrows(BusinessException.class,()->reports.energy(admin,q));}
    @Test void csvBoundsEncodingAndMalformedQuotesAreRejected(){assertThrows(BusinessException.class,()->DemoFileReader.read("old.xls",new byte[]{1}));assertThrows(BusinessException.class,()->DemoFileReader.read("large.csv",new byte[5*1024*1024+1]));assertThrows(BusinessException.class,()->DemoFileReader.read("bad.csv",new byte[]{(byte)0xff}));assertThrows(BusinessException.class,()->DemoFileReader.read("quote.csv","a,b\n\"x,y".getBytes(StandardCharsets.UTF_8)));StringBuilder b=new StringBuilder("a,b\n");for(int i=0;i<1001;i++)b.append("x,y\n");assertThrows(BusinessException.class,()->DemoFileReader.read("rows.csv",b.toString().getBytes(StandardCharsets.UTF_8)));}
    byte[] workbook(String sheetXml,String workbookXml,String extraName)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){Map<String,String> files=new LinkedHashMap<>();files.put("xl/workbook.xml",workbookXml);files.put("xl/_rels/workbook.xml.rels","<Relationships><Relationship Id=\"rId1\" Target=\"worksheets/sheet1.xml\"/></Relationships>");files.put("xl/worksheets/sheet1.xml",sheetXml);if(extraName!=null)files.put(extraName,"test");for(Map.Entry<String,String> f:files.entrySet()){zip.putNextEntry(new ZipEntry(f.getKey()));zip.write(f.getValue().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}return bytes.toByteArray();}
    @Test void xlsxReadsValuesAndRejectsFormulaMacroAndXmlEntity()throws Exception{String wb="<workbook xmlns:r=\"r\"><sheets><sheet name=\"设备导入\" r:id=\"rId1\"/></sheets></workbook>",sheet="<worksheet><sheetData><row><c r=\"A1\" t=\"inlineStr\"><is><t>设备编码</t></is></c></row><row><c r=\"A2\" t=\"inlineStr\"><is><t>0001</t></is></c></row></sheetData></worksheet>";assertEquals("0001",DemoFileReader.read("values.xlsx",workbook(sheet,wb,null)).get(1).get(0));byte[] formula=workbook(sheet.replace("<is><t>0001</t></is>","<f>1+1</f><v>2</v>"),wb,null);assertThrows(BusinessException.class,()->DemoFileReader.read("formula.xlsx",formula));byte[] macro=workbook(sheet,wb,"xl/vbaProject.bin");assertThrows(BusinessException.class,()->DemoFileReader.read("macro.xlsx",macro));byte[] xxe=workbook(sheet,"<!DOCTYPE workbook [<!ENTITY x SYSTEM 'file:///etc/passwd'>]>"+wb,null);assertThrows(BusinessException.class,()->DemoFileReader.read("xxe.xlsx",xxe));}
    Map<String,Object> response(String tool,Map<String,Object> args){return map("id","injected-test-response","choices",Arrays.asList(map("message",map("role","assistant","tool_calls",Arrays.asList(map("id",id("test"),"type","function","function",map("name",tool,"arguments",json(args))))))));}
    String run(){String id=id("TEST");repo.add("run",id,"F01","admin","running",map("run_type","test"));return id;}
    @Test void modelCannotInventEvidenceOrReturnUnverifiedBusinessAnswers(){when(client.complete(anyList(),anyList(),anyLong(),anyInt())).thenReturn(response("present_results",map("evidence_ids",Arrays.asList("made-up-999"))));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),Arrays.asList(present()),x->map(),System.currentTimeMillis()+10000));reset(client);when(client.status()).thenReturn(map("model","test"));when(client.complete(anyList(),anyList(),anyLong(),anyInt())).thenReturn(map("choices",Arrays.asList(map("message",map("content","共有999台设备")))));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),Arrays.asList(present()),x->map(),System.currentTimeMillis()+10000));}
    @Test void unknownToolIllegalParametersAndRepeatedCallsAreStopped(){List<Map<String,Object>> tools=Arrays.asList(tool("collect","read",map("factory_id",choice("scope","F01")),"factory_id"),present());when(client.complete(anyList(),anyList(),anyLong(),anyInt())).thenReturn(response("free_sql",map("sql","drop table")));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),tools,x->map(),System.currentTimeMillis()+10000));when(client.complete(anyList(),anyList(),anyLong(),anyInt())).thenReturn(response("collect",map("factory_id","F02")));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),tools,x->map(),System.currentTimeMillis()+10000));when(client.complete(anyList(),anyList(),anyLong(),anyInt())).thenReturn(response("collect",map("factory_id","F01")));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),tools,x->map("type","assets","total",36),System.currentTimeMillis()+10000));}
    @Test void cancelledAndOverBudgetRunsCannotExecuteTools(){String run=run();Map<String,Object> r=repo.get(run);r.put("state","cancelled");repo.save(r);assertThrows(BusinessException.class,()->engine.execute(admin,run,"test",new ArrayList<>(),Arrays.asList(present()),x->{fail("No tool may run");return map();},System.currentTimeMillis()+10000));assertThrows(BusinessException.class,()->engine.execute(admin,run(),"test",new ArrayList<>(),Arrays.asList(present()),x->map(),System.currentTimeMillis()-1));}
}
